[CmdletBinding()]param([string]$PackageRoot)
$ErrorActionPreference='Stop';$PSNativeCommandUseErrorActionPreference=$false;if([string]::IsNullOrWhiteSpace($PackageRoot)){$PackageRoot=Split-Path -Parent $PSScriptRoot};$root=(Resolve-Path $PackageRoot).Path;$payload=Join-Path $root payload;$pm=Get-Content -Raw (Join-Path $root manifest.json)|ConvertFrom-Json;$nvcuda=Join-Path $env:WINDIR System32\nvcuda.dll;$integrity=$true;foreach($p in $pm.base_payload_sha256.psobject.Properties){$integrity=$integrity-and(Get-FileHash (Join-Path $payload $p.Name)).Hash-eq$p.Value};foreach($p in $pm.variant_payload_sha256.psobject.Properties){$integrity=$integrity-and(Get-FileHash (Join-Path $payload ('variants\'+$p.Name))).Hash-eq$p.Value};$stamp=Get-Date -Format yyyyMMdd_HHmmss;$tag=if([string]::IsNullOrWhiteSpace([string]$pm.result_tag)){"n0_cta$([int]$pm.target_cta[0])_$([int]$pm.target_cta[1])_box_stage_sweep"}else{[string]$pm.result_tag};$work=Join-Path $root "_${tag}_work_$stamp";$result=Join-Path $root "_${tag}_reference_result_$stamp";New-Item -ItemType Directory -Path $work,$result|Out-Null
function Run($ptx,$tag,[int]$extra){$j=Join-Path $work "$tag.json";$s=Join-Path $work "$tag.scratch.raw";$o=Join-Path $work "$tag.output.raw";& (Join-Path $payload neural_reference_probe.exe) --nvcuda $nvcuda --ptx $ptx --function $pm.function --json $j --n0-input (Join-Path $payload input_rgba16f.raw) --n0-weights (Join-Path $payload weights.raw) --n0-params (Join-Path $payload params.raw) --n0-scratch-out $s --n0-output $o --n0-grid-x 80 --n0-grid-y 48 --n0-scratch-extra-bytes $extra *> (Join-Path $work "$tag.log");[ordered]@{exit=$LASTEXITCODE;json=$j;scratch=$s;output=$o}}
$base=Run (Join-Path $payload n0_original.ptx) baseline 0;$bp=Get-Content -Raw $base.json|ConvertFrom-Json;$baseHash=(Get-FileHash $base.output).Hash;$size=[int]$pm.trace_bytes_per_variant;$combined=[byte[]]::new($pm.variant_count*$size);$rows=@();$ok=$base.exit-eq 0-and$bp.pass
foreach($v in $pm.variants){$run=Run (Join-Path $payload ('variants\'+$v.filename)) $v.name ([int]$pm.scratch_extra_bytes);$probe=Get-Content -Raw $run.json|ConvertFrom-Json;$stream=[IO.File]::OpenRead($run.scratch);try{[void]$stream.Seek([int64]$pm.trace_offset,[IO.SeekOrigin]::Begin);$b=[byte[]]::new($size);if($stream.Read($b,0,$size)-ne$size){throw'short trace'};[Array]::Copy($b,0,$combined,[int]$v.index*$size,$size)}finally{$stream.Dispose()};$oh=(Get-FileHash $run.output).Hash;$preserved=$oh-eq$baseHash;$rows+=[ordered]@{index=[int]$v.index;name=$v.name;probe_exit=$run.exit;probe_pass=[bool]$probe.pass;output_sha256=$oh;output_preserved=$preserved;trace_sha256=(Get-FileHash -InputStream ([IO.MemoryStream]::new($b))).Hash};$ok=$ok-and$run.exit-eq 0-and$probe.pass-and$preserved}
$trace=Join-Path $result single_stage_traces.raw;[IO.File]::WriteAllBytes($trace,$combined);$pass=$integrity-and$ok;[ordered]@{schema=1;experiment='rtx_n0_box_stage_single_observation_sweep';status=if($pass){'PASS'}else{'FAIL'};payload_integrity=$integrity;device_name=$bp.device_name;baseline_output_sha256=$baseHash;target_cta=@([int]$pm.target_cta[0],[int]$pm.target_cta[1],0);trace_bytes_per_variant=$size;checkpoint_sha256=(Get-FileHash $trace).Hash;variants=$rows}|ConvertTo-Json -Depth 8|Set-Content (Join-Path $result manifest.json) -Encoding utf8;$zip="$result.zip";Compress-Archive $result $zip -CompressionLevel Optimal;Get-Content -Raw (Join-Path $result manifest.json);Write-Host "Result: $zip";exit $(if($pass){0}else{1})
